const API_BASE="/api";let currentPage=1,currentDate="",totalPages=1;async function loadHistory(){showLoading("Загрузка истории...");try{let e=`/api/history?page=${currentPage}&per_page=50`;currentDate&&(e+=`&date=${currentDate}`);const t=await fetch(e),n=await t.json();if(!n.success)throw new Error(n.error);renderHistory(n.history),renderPagination(n.pagination)}catch(e){console.error("Ошибка:",e),showError("Ошибка загрузки данных")}finally{hideLoading()}}function renderHistory(e){const t=document.getElementById("historyList");e&&0!==e.length?t.innerHTML=e.map(e=>{const t=new Date(e.created_at).toLocaleString("ru-RU",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"});let n="";const a=e.changed_fields||{};for(const e in a){const t=a[e];if("Примечания"===e&&"addition"===t.type){let a="";t.добавлено&&Array.isArray(t.добавлено)?a=t.добавлено.map(e=>e.text).join(" "):t.добавлено&&(a=t.добавлено),n+=`\n                    <div class="change-addition">\n                        <div class="change-addition-field">${escapeHtml(e)}</div>\n                        <div class="change-addition-text">➕ ${escapeHtml(a.trim())}</div>\n                    </div>\n                `}else n+=`\n                    <div class="change-item">\n                        <div class="change-field">${escapeHtml(e)}</div>\n                        <div class="change-old">${escapeHtml(t.было||"<пусто>")}</div>\n                        <div class="change-new">${escapeHtml(t.стало||"<пусто>")}</div>\n                    </div>\n                `}return`\n            <div class="history-item">\n                <div class="history-item-header">\n                    <a href="/add-draft?draft=${e.draft_id}&view=true" class="draft-title">\n                        ${escapeHtml(e.draft_display_name||"Неизвестный черновик")}\n                    </a>\n                    <span class="change-date">${t}</span>\n                </div>\n                <div class="changes-list">${n}</div>\n            </div>\n        `}).join(""):t.innerHTML='\n            <div class="empty-state">\n                <div class="icon">📭</div>\n                <h3>Нет записей в истории</h3>\n                <p>Изменения черновиков будут отображаться здесь</p>\n            </div>\n        '}function renderPagination(e){const t=document.getElementById("pagination");if(!e||e.total_pages<=1)return void(t.innerHTML="");totalPages=e.total_pages;let n="";n+=`<button onclick="changePage(${currentPage-1})" ${1===currentPage?"disabled":""}>←</button>`;for(let t=1;t<=e.total_pages;t++)1===t||t===e.total_pages||t>=currentPage-2&&t<=currentPage+2?n+=`<button onclick="changePage(${t})" ${t===currentPage?'class="active"':""}>${t}</button>`:t!==currentPage-3&&t!==currentPage+3||(n+="<button disabled>...</button>");n+=`<button onclick="changePage(${currentPage+1})" ${currentPage===e.total_pages?"disabled":""}>→</button>`,t.innerHTML=n}function changePage(e){e<1||e>totalPages||(currentPage=e,loadHistory())}function initFilters(){const e=document.getElementById("applyFilterBtn"),t=document.getElementById("clearFilterBtn"),n=document.getElementById("dateFilter");e.addEventListener("click",()=>{currentDate=n.value,currentPage=1,loadHistory()}),t.addEventListener("click",()=>{n.value="",currentDate="",currentPage=1,loadHistory()})}function showLoading(e){const t=document.getElementById("statusMessage");t.innerHTML=`<div class="loading">${e}</div>`,t.className="status-message info",t.style.display="block"}function hideLoading(){document.getElementById("statusMessage").style.display="none"}function showError(e){document.getElementById("historyList").innerHTML=`\n        <div class="empty-state">\n            <div class="icon">⚠️</div>\n            <h3>Ошибка загрузки</h3>\n            <p>${escapeHtml(e)}</p>\n        </div>\n    `}function escapeHtml(e){if(!e)return"";const t=document.createElement("div");return t.textContent=e,t.innerHTML}document.addEventListener("DOMContentLoaded",function(){loadHistory(),initFilters()});